UISprayCanEmitter=function(game){Phaser.Particles.Arcade.Emitter.call(this,game,0,0,400);this.particleClass=UISprayCanParticle;this.makeParticles();this.minParticleSpeed.setTo(UIConstants.SPRAY_MIN_X_SPEED,UIConstants.SPRAY_MIN_Y_SPEED);this.maxParticleSpeed.setTo(UIConstants.SPRAY_MAX_X_SPEED,UIConstants.SPRAY_MAX_Y_SPEED);this.particleDrag.setTo(UIConstants.SPRAY_DRAG,UIConstants.SPRAY_DRAG);this.setAlpha(0.5,0.7);this.setRotation(0,0);this.minParticleScale=0.8;this.maxParticleScale=1.0;this.gravity=0;this.sprayCan=null;this.kill();this.visible=false;};UISprayCanEmitter.prototype=Object.create(Phaser.Particles.Arcade.Emitter.prototype);UISprayCanEmitter.prototype.constructor=UISprayCanEmitter;UISprayCanEmitter.prototype.update=function(){if(!this.exists){return;}this.x=this.sprayCan.world.x+this.sprayCan.width*UIConstants.GARAGE_SPRAY_OFFSET_X;this.y=this.sprayCan.world.y+this.sprayCan.height*UIConstants.GARAGE_SPRAY_OFFSET_Y;Phaser.Particles.Arcade.Emitter.prototype.update.call(this);if(this.countLiving()==0){this.kill();this.visible=false;}};UISprayCanEmitter.prototype.postUpdate=function(){if(!this.exists){return;}Phaser.Particles.Arcade.Emitter.prototype.postUpdate.call(this);};UISprayCanEmitter.prototype.spawn=function(sprayCan,currentEmitter){this.revive();this.visible=true;this.sprayCan=sprayCan;this.x=this.sprayCan.world.x+this.sprayCan.width*UIConstants.GARAGE_SPRAY_OFFSET_X;this.y=this.sprayCan.world.y+this.sprayCan.height*UIConstants.GARAGE_SPRAY_OFFSET_Y;UISprayCanParticle.setCurrentEmitter(currentEmitter);UISprayCanParticle.setColour(this.game,sprayCan.getColour());this.flow(UIConstants.GARAGE_SPRAY_PARTICLE_TIME,16,10,UIConstants.GARAGE_SPRAY_TIME/16*10);};UISprayCanEmitter.prototype.remove=function(){this.on=false;};UISprayCanEmitter.prototype.retire=function(){this.kill();this.visible=false;this.callAll('retire');};